WITH enriched AS (SELECT *, RANK() OVER (PARTITION BY event_type ORDER BY duration_sec DESC NULLS FIRST) duration_sec_rank, AVG(duration_sec) OVER (PARTITION BY session_id ORDER BY duration_sec ASC, id ASC ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) duration_sec_avg_3, AVG(duration_sec) OVER (PARTITION BY event_type ORDER BY event_time ASC, id ASC ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) duration_sec_avg_6, AVG(duration_sec) OVER (PARTITION BY session_id ORDER BY CAST(event_time AS BIGINT) ASC RANGE BETWEEN 7776000 PRECEDING AND CURRENT ROW) duration_sec_avg_90d, RANK() OVER (ORDER BY duration_sec DESC) duration_sec_rank_2 FROM web_events) SELECT id, session_id, page, event_time, duration_sec, duration_sec_avg_90d, duration_sec_rank_2 FROM enriched ORDER BY duration_sec_avg_90d ASC;
